query.malloy:
run: sales -> {
  group_by: 地域
  aggregate: revenue is 金額.sum()
}

run: sales -> {
  where: 金額 >= 100000
  group_by: 月 is 受注日.month
  aggregate: revenue is 金額.sum()
}

run: sales -> {
  group_by: 顧客
  aggregate: 受注回数 is count(受注番号)
} -> {
  group_by: 受注回数
  aggregate: 顧客数 is count()
  order_by: 受注回数
}
